# ---------------------------------------------------------------------------------------------- boot
def boot(cfg):
    CONFIG.update(cfg)
    os.makedirs(STATE_DIR, exist_ok=True)
    for svc in CONFIG.get("services", []):
        threading.Thread(target=relay, args=(svc,), daemon=True).start()
    for cmd in CONFIG.get("boot", []):
        r = run(cmd, timeout=120)
