def _scratch_slot(nonblocking: bool = False):
    slot_dir = os.path.join(CACHE_ROOT, "slots")
    os.makedirs(slot_dir, exist_ok=True)
    start = os.getpid() % MAX_SCRATCH_SLOTS
    for off in range(MAX_SCRATCH_SLOTS):
        idx = (start + off) % MAX_SCRATCH_SLOTS
        p = os.path.join(slot_dir, f"slot-{idx}.lock")
        fd = os.open(p, os.O_CREAT | os.O_RDWR, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            os.close(fd)
            continue
        try:
            yield idx
            return
        finally:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            finally:
                os.close(fd)
    if nonblocking:
        raise BlockingIOError("all scratch slots busy")
    p = os.path.join(slot_dir, f"slot-{start}.lock")
    with _file_lock(p):
        yield start


def _create_sandbox(env: str | None = None, tenant: str | None = None,
                    clock_offset: float | None = None, snapshot: str | None = None) -> sbx.Sandbox:
    """Create a sandbox, backing off briefly if close to the per-user live sandbox limit."""
    deadline = time.time() + 15.0
    while True:
        try:
            live = len(sbx.list_sandboxes().get("sandboxes", []))
        except Exception:
            live = 0
        if live >= LIVE_SANDBOX_HARD_LIMIT and time.time() < deadline:
            time.sleep(0.2)
            continue
        try:
            return sbx.create(env=env, tenant=tenant, clock_offset=clock_offset, snapshot=snapshot)
        except sbx.SandboxError as exc:
            msg = str(exc).lower()
            if ("limit" in msg or "too many" in msg or "128" in msg) and time.time() < deadline:
                time.sleep(0.25)
                continue
            raise


# ---------------------------------------------------------------------------
