                sa["fp"] == sb_st["fp"]
                and sa["mfp"] == sb_st["mfp"]
                and sa["jrn"] == sb_st["jrn"]
            )
            if not same_state and int(tr["sent_at"]) != int(tr["captured_at"]):
                oa, ob = ta["obs_ok"][k_idx], tb["obs_ok"][k_idx]
                if oa != ob:
                    win_clk = ta["clocks_used"][i] if oa else tb["clocks_used"][i]
                    fixed_secs[i] = int(win_clk)

