            _drop_trial_snaps(ta)
            ta, tb = _run_trial_pair(traj, info, rdir, fixed_secs=fixed_secs)

        non_admin_names = {s["name"] for s in info.get("services", []) if not s.get("admin")}
        eg = ta["egress"]
        non_admin_mut_turns = []
        for i in range(len(turns)):
            s_len = ta["steps"][i]["eg_len"]
            e_len = ta["steps"][i + 1]["eg_len"]
            for rec in eg[s_len:e_len]:
                if rec.get("service") in non_admin_names:
                    method = (rec.get("request") or "").split(" ", 1)[0].upper()
                    if method not in ("GET", "HEAD", "OPTIONS"):
