        common_non_admin_gets: dict[str, dict[str, str]] = {}
        for sname in non_admin_names:
            ga = ta["non_admin_gets"].get(sname, {})
            gb = tb["non_admin_gets"].get(sname, {})
            common_non_admin_gets[sname] = {
                p: sha for p, sha in ga.items() if gb.get(p) == sha
