                "fp": sa["fp"] if resettable else None,
                "mfp": sa["mfp"] if resettable else None,
                "jrn": sa["jrn"] if resettable else None,
                "last_rc": sa["last_rc"],
                "has_bg_proc": sa["has_bg_proc"],
                "fast_path": bool(resettable and sa["can_fast"]),
