        _drop_trial_snaps(ta, keep_ids=keep_snaps)

        meta = {
            "env": traj["env"],
            "info": info,
            "rdir": rdir,
            "init_fp": ta["init_fp"],
            "fixed_secs": {str(k): v for k, v in fixed_secs.items()},
            "non_admin_mut_turns": non_admin_mut_turns,
