        with open(tmp, "w") as f:
            json.dump(meta, f)
        os.replace(tmp, meta_path)
        _evict_old_rollouts()
        return meta


# ---------------------------------------------------------------------------
# Tenant synchronization & non-admin mock tap/replay
# ---------------------------------------------------------------------------

def _sync_tenant(sb: sbx.Sandbox, info: dict, rdir: str,
                 target_mfp: dict, target_jrn: dict,
                 non_admin_gets: dict) -> None:
    mounts = info.get("mounts", [])
    admin_sync = [
        {"name": s["name"], "host": s["host"], "port": s["port"], "target": target_jrn[s["name"]]}
        for s in info.get("services", [])
        if s.get("admin")
    ]
    non_admin_verify = [
        {"name": s["name"], "host": s["host"], "port": s["port"], "expected": non_admin_gets.get(s["name"], {})}
        for s in info.get("services", [])
        if not s.get("admin") and non_admin_gets.get(s["name"])
    ]

    r = sb.exec([
        "python3", "-c", _SYNC_TENANT_PY,
        json.dumps(mounts),
        json.dumps(admin_sync),
        json.dumps(non_admin_verify),
    ])
    if r["rc"] != 0:
        raise NotResettable(f"tenant sync failed: {r['stderr']}")
    res = json.loads(r["stdout"])
    if not res.get("ok"):
        raise NotResettable(res.get("reason", "tenant drifted"))

    cur_mfp = res["mfp"]
    for m in mounts:
        mname, mpath = m["name"], m["path"]
        exp_h = target_mfp[mname]
        if cur_mfp.get(mname) != exp_h:
            targz = os.path.join(rdir, "mounts", f"{exp_h}.tar.gz")
            if not os.path.exists(targz):
                raise NotResettable(f"missing volume archive {exp_h}")
            with open(targz, "rb") as f:
                raw_b64 = base64.b64encode(f.read()).decode()
            cmd = (
                f"find {mpath} -mindepth 1 -maxdepth 1 -exec rm -rf -- {{}} + && "
                f"base64 -d | tar -xzpf - -C {mpath}"
            )
            xr = sb.exec(["sh", "-c", cmd], stdin=raw_b64)
            if xr["rc"] != 0:
                raise NotResettable(f"volume restore failed: {xr['stderr']}")


def _parse_hosts_ips(hosts_text: str, hostnames: set[str]) -> dict[str, str]:
    mapping = {}
    for ln in hosts_text.splitlines():
        ln = ln.split("#", 1)[0].strip()
        if not ln:
            continue
        parts = ln.split()
        if len(parts) >= 2:
            ip = parts[0]
            for h in parts[1:]:
                if h in hostnames:
                    mapping[h] = ip
    return mapping


def _get_or_record_non_admin_tap(traj: dict, meta: dict) -> dict[str, list[dict]]:
    rdir = meta["rdir"]
    tap_path = os.path.join(rdir, "non_admin_tap.json")
    if os.path.exists(tap_path):
        with open(tap_path) as f:
            return json.load(f)

    lock_path = os.path.join(rdir, "tap.lock")
    with _file_lock(lock_path):
        if os.path.exists(tap_path):
            with open(tap_path) as f:
                return json.load(f)

        info = meta["info"]
        non_admin_svcs = [s for s in info.get("services", []) if not s.get("admin")]
        fixed_secs = {int(k): v for k, v in meta.get("fixed_secs", {}).items()}
        turns = traj["turns"]

        with _scratch_slot(nonblocking=False):
            boot_target = float(traj["created_at"]) - 0.15
            sb = _create_sandbox(traj["env"], clock_offset=boot_target - time.time())
            try:
                hosts_txt = sb.exec(["cat", "/etc/hosts"])["stdout"]
                ip_map = _parse_hosts_ips(hosts_txt, {s["host"] for s in non_admin_svcs})
                tap_cfg = []
                sed_Parts = []
                for idx, s in enumerate(non_admin_svcs):
                    orig_ip = ip_map.get(s["host"])
                    if not orig_ip:
                        continue
                    mock_ip = f"127.0.0.{190 + idx}"
                    tap_cfg.append({
                        "name": s["name"],
                        "orig_ip": orig_ip,
                        "mock_ip": mock_ip,
                        "port": s["port"],
                        "out": f"/run/sbx/tap_{s['name']}.jsonl",
                    })
                    sed_Parts.append(f"s/{orig_ip}/{mock_ip}/g")

                if tap_cfg:
                    sb.exec(["sh", "-c", f"cp /etc/hosts /run/sbx/hosts.bak && sed -i '{';'.join(sed_Parts)}' /etc/hosts"])
                    sb.exec([
                        "sh", "-c",
                        'nohup python3 -c "$1" "$2" >/dev/null 2>&1 & while [ ! -f /run/sbx/tap.pid ]; do sleep 0.02; done',
                        "_", _TAP_DAEMON_PY, json.dumps(tap_cfg),
                    ])

                init_clk = _turn_clock(turns[0], "canonical", fixed_secs.get(0)) if turns else float(traj["ended_at"])
                _init_dynamic_clock(sb, init_clk)
                for i, tr in enumerate(turns):
                    t_clk = _turn_clock(tr, "canonical", fixed_secs.get(i))
                    _play_turn(sb, tr, t_clk)
                    if meta["steps"][i + 1]["has_bg_proc"]:
                        next_t = float(turns[i + 1]["sent_at"]) if i + 1 < len(turns) else float(traj["ended_at"])
                        gap = max(0.0, min(10.0, next_t - float(tr["captured_at"])))
                        if gap > 0.05:
                            time.sleep(gap)

                recorded: dict[str, list[dict]] = {}
                for item in tap_cfg:
                    r = sb.exec(["sh", "-c", f"cat {item['out']} 2>/dev/null || true"])
                    recorded[item["name"]] = [
                        json.loads(ln) for ln in r["stdout"].splitlines() if ln.strip()
                    ]
                tmp = f"{tap_path}.tmp.{os.getpid()}"
                with open(tmp, "w") as f:
                    json.dump(recorded, f)
                os.replace(tmp, tap_path)
                return recorded
            finally:
                with contextlib.suppress(Exception):
                    sb.terminate()


# ---------------------------------------------------------------------------
# Entry point: reset(traj, k)
# ---------------------------------------------------------------------------

def reset(traj: dict, k: int) -> str:
    turns = traj.get("turns")
    if turns is None or isinstance(k, bool) or not isinstance(k, int) or k < 0 or k > len(turns):
        raise NotResettable(f"invalid step k={k!r}")

    meta = _get_or_analyze_rollout(traj)
    step_meta = meta["steps"][k]
    if not step_meta["resettable"]:
        raise NotResettable(f"rollout {traj.get('traj_id')!r} step {k} is not resettable")

    env = traj["env"]
    tenant = traj["tenant"]
    info = meta["info"]
    rdir = meta["rdir"]
    non_admin_gets = meta["non_admin_gets"]
    target_time = float(turns[k]["sent_at"]) if k < len(turns) else float(traj["ended_at"])

    tenant_lock = os.path.join(CACHE_ROOT, "locks", f"tenant-{tenant}.lock")
    with _file_lock(tenant_lock):
        # Path 1: k == 0 (initial state before any keys were typed)
        if k == 0:
            sb = _create_sandbox(env=env, tenant=tenant, clock_offset=target_time - (time.time() + 0.40))
            try:
                _sync_tenant(sb, info, rdir, step_meta["mfp"], step_meta["jrn"], non_admin_gets)
                if sb.fingerprint()["fingerprint"] != step_meta["fp"]:
                    raise NotResettable("step 0 fingerprint mismatch")
                return sb.id
            except Exception:
                with contextlib.suppress(Exception):
                    sb.terminate()
                raise

        # Path 2: Snapshot fast-path (when shell, processes, ports, repl, and local services match initial boot)
        if step_meta["fast_path"]:
            snap_id = step_meta.get("snapshot")
            sb = None
            try:
                sb = _create_sandbox(
                    env=env,
                    tenant=tenant,
                    clock_offset=target_time - (time.time() + 0.55),
                    snapshot=snap_id,
                )
            except sbx.SandboxError:
                sb = None

            if sb is not None:
                try:
                    _sync_tenant(sb, info, rdir, step_meta["mfp"], step_meta["jrn"], non_admin_gets)
                    _restore_screen(sb, turns[k - 1]["observation"], last_rc=step_meta["last_rc"])
                    fp_now = sb.fingerprint()["fingerprint"]
                    scr_ok = _norm_screen(sb.capture()) == _norm_screen(turns[k - 1]["observation"])
                    if fp_now == step_meta["fp"] and scr_ok:
                        return sb.id
                except NotResettable:
                    with contextlib.suppress(Exception):
                        sb.terminate()
                    raise
                except Exception:
                    pass
                with contextlib.suppress(Exception):
                    sb.terminate()

        # Path 3: Prefix replay on tenant sandbox
        fixed_secs = {int(idx): sec for idx, sec in meta.get("fixed_secs", {}).items()}
        need_non_admin_mock = any(i < k for i in meta.get("non_admin_mut_turns", []))
        tap_data = _get_or_record_non_admin_tap(traj, meta) if need_non_admin_mock else {}

        est_dur = 0.55
        for i in range(k):
            est_dur += float(turns[i]["duration"]) + 0.05
            if meta["steps"][i + 1]["has_bg_proc"]:
                next_t = float(turns[i + 1]["sent_at"]) if i + 1 < len(turns) else float(traj["ended_at"])
                est_dur += max(0.0, min(10.0, next_t - float(turns[i]["captured_at"])))

        final_off = target_time - (time.time() + est_dur)
        sb = _create_sandbox(env=env, tenant=tenant, clock_offset=final_off)
        try:
            # Reset mounts and admin services to step 0 before replaying turns[:k]
            step0 = meta["steps"][0]
            _sync_tenant(sb, info, rdir, step0["mfp"], step0["jrn"], non_admin_gets)

            mock_started = False
            if need_non_admin_mock:
                non_admin_svcs = [s for s in info.get("services", []) if not s.get("admin")]
                hosts_txt = sb.exec(["cat", "/etc/hosts"])["stdout"]
                ip_map = _parse_hosts_ips(hosts_txt, {s["host"] for s in non_admin_svcs})
                rep_cfg = []
                sed_parts = []
                for idx, s in enumerate(non_admin_svcs):
                    orig_ip = ip_map.get(s["host"])
                    if not orig_ip:
                        continue
                    mock_ip = f"127.0.0.{190 + idx}"
                    rep_cfg.append({
                        "mock_ip": mock_ip,
                        "port": s["port"],
                        "entries": tap_data.get(s["name"], []),
                    })
                    sed_parts.append(f"s/{orig_ip}/{mock_ip}/g")
                if rep_cfg:
                    sb.exec(["sh", "-c", f"cp /etc/hosts /run/sbx/hosts.bak && sed -i '{';'.join(sed_parts)}' /etc/hosts"])
                    sb.exec([
                        "sh", "-c",
                        'nohup python3 -c "$1" "$2" >/dev/null 2>&1 & while [ ! -f /run/sbx/mock.pid ]; do sleep 0.02; done',
                        "_", _REPLAY_DAEMON_PY, json.dumps(rep_cfg),
                    ])
                    mock_started = True

            init_clk = _turn_clock(turns[0], "canonical", fixed_secs.get(0))
            _init_dynamic_clock(sb, init_clk)
            for i in range(k):
                t_clk = _turn_clock(turns[i], "canonical", fixed_secs.get(i))
                _play_turn(sb, turns[i], t_clk)
                if meta["steps"][i + 1]["has_bg_proc"]:
                    next_t = float(turns[i + 1]["sent_at"]) if i + 1 < len(turns) else float(traj["ended_at"])
                    gap = max(0.0, min(10.0, next_t - float(turns[i]["captured_at"])))
                    if gap > 0.05:
                        time.sleep(gap)

            if mock_started:
                sb.exec([
                    "sh", "-c",
                    "mv /run/sbx/hosts.bak /etc/hosts && "
                    "if [ -f /run/sbx/mock.pid ]; then kill -9 $(cat /run/sbx/mock.pid) 2>/dev/null || true; rm -f /run/sbx/mock.pid; fi",
                ])
                time.sleep(0.06)

            # Align dynamic clock file with target_time for all subsequent branch commands
            now_off = target_time - time.time()
            sb.exec(["sh", "-c", f"printf '%+.3f\\n' {now_off:.3f} > /run/sbx/ft"])

            # Verify final tenant state and sandbox fingerprint match step k
            _sync_tenant(sb, info, rdir, step_meta["mfp"], step_meta["jrn"], non_admin_gets)
            if sb.fingerprint()["fingerprint"] != step_meta["fp"]:
                raise NotResettable("post-replay fingerprint mismatch")
            return sb.id
        except Exception:
            with contextlib.suppress(Exception):
                sb.terminate()
            raise

